/*
 * A332823  A 3-way classification indicator generated by the products of two
 *          consecutive primes and the cubes of primes. a(n) is -1, 0, or 1
 *          such that a(n) == A048675(n) (mod 3).
 * https://oeis.org/A332823
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign
 * Formula:   not stated
 * Range:     i8 n <= 9860, i16 n <= 9860, i32 n <= 9860, i64 n <= 9860,
 *            i128 n <= 9860, big any n
 * Helpers:   build_primes_upto
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A332823: 3‑way classification indicator.
 *  a(n) equals the sum of prime exponents weighted by
 *  (+1) for primes at odd indices and (–1) for primes at even indices,
 *  taken modulo 3.  Equivalently, a(n) ≡ A048675(n) (mod 3).
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/build_primes_upto.h"

/*  Return a(n) for n >= 1.
 *  The function is memoised via a static prime sieve that is built once.
 */
seq_t a(idx_t n)
{
    if (n == 1u) return 0;      /* offset 1 */

    /* Initialise a prime list large enough for the expected input range. */
    static bool  init = false;
    static uint64_t *primes = NULL;
    static size_t   prime_cnt = 0;

    if (!init) {
        /* 1 000 000 is more than enough for n up to ~10⁴ (and very safe for larger)
           if a larger limit is required it can be increased without changing the logic. */
        build_primes_upto(1000000, &primes, &prime_cnt);
        init = true;
    }

    seq_t sum = 0;               /* running signed sum */
    uint64_t m   = (uint64_t)n;  /* work on a 64‑bit copy for factorisation */

    for (size_t i = 0; i < prime_cnt && primes[i] * primes[i] <= m; ++i) {
        if (m % primes[i] == 0) {
            uint64_t p   = primes[i];
            int      exp = 0;
            while (m % p == 0) {
                ++exp;
                m /= p;
            }
            seq_t sign = (i & 1) ? (seq_t)(-1) : (seq_t)1;  /* odd index → +1, even → -1 */
            sum += sign * (seq_t)exp;
        }
    }

    /* Any remaining factor is prime and larger than the sieve limit.
       Its index (parity) can be found by extending the sieve just enough. */
    if (m > 1) {
        size_t idx = prime_cnt;           /* default index if we discover the prime later */
        for (size_t j = 0; j < prime_cnt; ++j) {
            if (primes[j] == m) { idx = j; break; }
        }

        if (idx == prime_cnt) {   /* prime not yet in the list */
            uint64_t candidate = primes[prime_cnt - 1] + 1;

            /* Extend sieve until we find the needed prime. */
            while (candidate <= m) {
                bool is_prime = true;
                for (size_t k = 0; k < prime_cnt && primes[k] * primes[k] <= candidate; ++k) {
                    if (candidate % primes[k] == 0) { is_prime = false; break; }
                }
                ++candidate;
                if (is_prime) {
                    primes = (uint64_t*)realloc(primes,
                                                sizeof(uint64_t) * (prime_cnt + 1));
                    primes[prime_cnt++] = candidate - 1;
                    if (candidate - 1 == m) { idx = prime_cnt - 1; break; }
                }
            }
        }

        seq_t sign = (idx & 1) ? (seq_t)(-1) : (seq_t)1;
        sum += sign * (seq_t)1;   /* one remaining prime factor */
    }

    /* Reduce to a signed residue in {-1,0,1} modulo 3. */
    int mod = (int)((sum % 3 + 3) % 3);   /* 0,1,2 */
    if (mod == 2) return (seq_t)(-1);     /* 2 ≡ –1 (mod 3) */
    return (seq_t)mod;                    /* 0 or 1 */
}
